package com.foxhole.vpn.ui

import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.Base64
import kotlin.math.sqrt

// Fixed island selection at a 400dp reference size avoids detail changes during rotation.
internal object PlanetMeshData {
    const val vertexCount: Int = 6968
    const val triangleCount: Int = 7586

    val vertices: FloatArray by lazy {
        val input = buffer(vertexChunks)
        FloatArray(vertexCount * 3).also { result ->
            for (index in 0 until vertexCount) {
                val x = input.short.toFloat() / 32767f
                val y = input.short.toFloat() / 32767f
                val z = input.short.toFloat() / 32767f
                val length = sqrt(x * x + y * y + z * z)
                result[index * 3] = x / length
                result[index * 3 + 1] = y / length
                result[index * 3 + 2] = z / length
            }
        }
    }

    val triangles: IntArray by lazy {
        val input = buffer(triangleChunks)
        IntArray(triangleCount * 3) { input.short.toInt() and 0xffff }
    }

    private fun buffer(chunks: Array<String>): ByteBuffer =
        ByteBuffer.wrap(Base64.getDecoder().decode(chunks.joinToString("")))
            .order(ByteOrder.LITTLE_ENDIAN)

